//   non-null optedOutAt blocks all texts (fail closed). The FCC "revoke-all"
//   provision in (a)(10) has a delayed and changing effective date, so counsel
//   must confirm whether a STOP to marketing may still allow transactional.

input.command:
mkdir -p /tmp/sms-gate-test && cat > /tmp/sms-gate-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g1-2/bot.mjs';

const ok = { allowed: true, reason: null };
const base = (over = {}) => ({
  kind: 'marketing',
  body: 'Flash sale today! Reply STOP to opt out.',
  to: { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: null },
  ...over,
});
const withTo = (t) => base({ to: { ...base().to, ...t } });
// 2026-10-22 local-hour helpers: build instants from a Chicago wall-clock hour (CDT = UTC-5 in October)
const chicago = (h) => new Date(Date.UTC(2026, 9, 22, h + 5, 30));

const cases = [
  ['marketing allowed at noon Chicago', base(), chicago(12), ok],
  ['marketing 8:00 Chicago allowed (inclusive start)', base(), chicago(8), ok],
  ['marketing 20:59 Chicago allowed', base(), new Date(Date.UTC(2026, 9, 23, 1, 59)), ok],
  ['marketing 21:00 Chicago blocked', base(), new Date(Date.UTC(2026, 9, 23, 2, 0)), { allowed: false, reason: 'quiet_hours' }],
  ['marketing 07:59 Chicago blocked', base(), new Date(Date.UTC(2026, 9, 22, 12, 59)), { allowed: false, reason: 'quiet_hours' }],
  ['no consent', withTo({ marketingConsent: false }), chicago(12), { allowed: false, reason: 'no_marketing_consent' }],
  ['missing STOP language', base({ body: 'Flash sale today!' }), chicago(12), { allowed: false, reason: 'missing_opt_out_language' }],
  ['opted out marketing', withTo({ optedOutAt: '2026-10-01T10:00:00Z' }), chicago(12), { allowed: false, reason: 'opted_out' }],
  ['bad time zone', withTo({ timeZone: 'Mars/Olympus' }), chicago(12), { allowed: false, reason: 'invalid_time_zone' }],
  ['transactional at 3am allowed', base({ kind: 'transactional', body: 'Your code is 445892.' }), new Date(Date.UTC(2026, 9, 22, 8, 0)), ok],
  ['transactional without consent allowed', base({ kind: 'transactional', body: 'Your code is 445892.', to: { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: false, optedOutAt: null } }), chicago(12), ok],
  ['transactional after STOP blocked', base({ kind: 'transactional', body: 'Your code is 445892.', to: { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: false, optedOutAt: '2026-10-01T10:00:00Z' } }), chicago(12), { allowed: false, reason: 'opted_out' }],
  ['bad phone (no +1)', withTo({ phone: '3125550142' }), chicago(12), { allowed: false, reason: 'invalid_phone_number' }],
  ['bad phone (area code starts 1)', withTo({ phone: '+11125550142' }), chicago(12), { allowed: false, reason: 'invalid_phone_number' }],
  ['empty body', base({ body: '   ' }), chicago(12), { allowed: false, reason: 'empty_body' }],
  ['unknown kind', base({ kind: 'promo' }), chicago(12), { allowed: false, reason: 'unknown_message_kind' }],
  ['invalid date', base(), new Date('nope'), { allowed: false, reason: 'invalid_timestamp' }],
  ['not a Date', base(), '2026-10-22', { allowed: false, reason: 'invalid_timestamp' }],
  ['null message', null, chicago(12), { allowed: false, reason: 'invalid_message' }],
];

let fails = 0;
for (const [name, msg, now, want] of cases) {
  const got = checkSms(msg, now);
  try { assert.deepEqual(got, want); console.log('PASS', name); }
  catch { fails++; console.log('FAIL', name, JSON.stringify(got), 'want', JSON.stringify(want)); }
}
console.log(fails === 0 ? `all ${cases.length} passed` : `${fails} failed`);
process.exitCode = fails ? 1 : 0;
EOF
cd /tmp/sms-gate-test && for tz in UTC Asia/Tokyo Pacific/Honolulu; do echo "== server TZ=$tz"; TZ=$tz node test.mjs | tail -n 3; done; TZ=Asia/Tokyo node test.mjs | grep -c PASS; TZ=Asia/Tokyo node test.mjs | grep FAIL; echo "exit=$?"
